function makeQs(c){return QUESTION_BANK[c].map((q,i)=>({id:i+1,q:q.q,opts:q.opts,ans:q.ans}));}
function load(){try{return JSON.parse(localStorage.getItem(DBKEY))||{students:[],results:[],examOpen:true,published:false}}catch{return {students:[],results:[],examOpen:true,published:false}}}
let db=load(),activeStudent=null,examTimer=null,remaining=0;
function save(){localStorage.setItem(DBKEY,JSON.stringify(db))}
function toast(t){let e=document.getElementById('toast');e.textContent=t;e.style.display='block';setTimeout(()=>e.style.display='none',2800)}
function modal(html){document.getElementById('modalContent').innerHTML=html;document.getElementById('modal').classList.remove('hidden')}
function close(){document.getElementById('modal').classList.add('hidden');if(examTimer)clearInterval(examTimer);examTimer=null}
document.getElementById('closeModal').onclick=close;document.getElementById('modal').addEventListener('click',e=>{if(e.target.id==='modal')close()});
document.getElementById('classGrid').innerHTML=classes.map(c=>`<div class="class-card"><strong>Class ${c}</strong><small>${durations[c]} minute exam</small><p>Time slot: ${slots[c]}</p></div>`).join('');
document.getElementById('registerOpen').onclick=showRegister;
document.getElementById('loginOpen').onclick=showLogin;
document.getElementById('adminOpen').onclick=()=>modal(`<h2>Administrator login</h2><p class="muted">Demo administrator access. This PIN is not secure for public deployment.</p><div class="field"><label>ADMIN PIN</label><input id="adminPin" type="password" placeholder="Enter admin PIN"></div><button class="primary wide" id="adminLogin" style="margin-top:14px">Open dashboard</button>`);
function showRegister(){modal(`<h2>Free student registration</h2><p class="muted">Complete all required fields. A unique Olympiad ID will be generated.</p><form id="regForm"><div class="form-grid">
<div class="field"><label>Student full name *</label><input name="name" required maxlength="70"></div>
<div class="field"><label>Class *</label><select name="cls" required>${classes.map(c=>`<option value="${c}">Class ${c}</option>`).join('')}</select></div>
<div class="field"><label>School name *</label><input name="school" required maxlength="100"></div>
<div class="field"><label>City / District *</label><input name="city" required maxlength="70"></div>
<div class="field"><label>Student / Parent mobile *</label><input name="phone" required inputmode="numeric" pattern="[0-9]{10}" maxlength="10"></div>
<div class="field"><label>Parent / Guardian name *</label><input name="guardian" required maxlength="70"></div>
<div class="field full"><label>Email (optional)</label><input name="email" type="email" maxlength="100"></div></div><button class="primary wide">Submit free registration</button></form><p class="muted">By registering, the parent/guardian confirms that the details are correct and consents to their use for administering this competition.</p>`);
document.getElementById('regForm').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),v=Object.fromEntries(f.entries());v.cls=Number(v.cls);if(db.students.some(s=>s.phone===v.phone&&s.cls===v.cls)){toast('A registration with this mobile number and class already exists.');return}v.id='SBS26-'+String(Date.now()).slice(-7);v.created=new Date().toISOString();db.students.push(v);save();modal(`<h2>Registration successful!</h2><div class="success-panel">Your registration has been saved on this device.</div><p>Your Olympiad ID:</p><div class="id-code">${v.id}</div><p class="muted">Please save this ID. You will need it to log in.</p><button class="primary wide" onclick="navigator.clipboard?.writeText('${v.id}');">Copy registration ID</button><button class="secondary wide" style="margin-top:8px" onclick="showLogin()">Continue to student login</button>`)}}
function showLogin(){modal(`<h2>Student login</h2><p class="muted">Enter your Olympiad ID and registered mobile number.</p><form id="loginForm"><div class="field"><label>Olympiad ID</label><input name="id" required placeholder="SBS26-XXXXXXX"></div><div class="field" style="margin-top:12px"><label>Registered mobile number</label><input name="phone" required inputmode="numeric" maxlength="10"></div><button class="primary wide" style="margin-top:18px">Login</button></form>`);document.getElementById('loginForm').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),s=db.students.find(x=>x.id===f.get('id').trim().toUpperCase()&&x.phone===f.get('phone'));if(!s){toast('Details not found. Check your ID and mobile number.');return}activeStudent=s;showStudent()}}
function showStudent(){let s=activeStudent,r=db.results.find(x=>x.id===s.id);modal(`<h2>Welcome, ${esc(s.name)}</h2><p class="muted">Olympiad ID: <b>${s.id}</b> · Class ${s.cls} · ${esc(s.school)}</p><div class="success-panel"><b>Exam time slot:</b> ${slots[s.cls]}<br><b>Duration:</b> ${durations[s.cls]} minutes</div>${!db.examOpen?'<p class="admin-note">The examination is currently closed by the organiser.</p>':r?'<p class="admin-note">Your attempt has already been submitted. Only one attempt is allowed.</p>':`<button class="primary wide" id="startExam">Start Class ${s.cls} examination</button>`}${r?`<h3>Your result</h3><p><b>${r.score} / ${r.total}</b> (${Math.round(r.score/r.total*100)}%)</p>${db.published?`<button class="secondary wide" id="certBtn">View participation certificate</button>`:'<p class="muted">Results and certificates will be available after publication.</p>'}`:''}${db.published?`<button class="secondary wide" id="studentCert" style="margin-top:8px">Participation certificate</button>`:''}`);
if(document.getElementById('startExam'))document.getElementById('startExam').onclick=()=>startExam(s);
if(document.getElementById('studentCert'))document.getElementById('studentCert').onclick=()=>certificate(s,r);
if(document.getElementById('certBtn'))document.getElementById('certBtn').onclick=()=>certificate(s,r)}
function startExam(s){if(!db.examOpen||db.results.some(r=>r.id===s.id)){toast('Exam unavailable or attempt already used.');return}let qs=makeQs(s.cls),mins=durations[s.cls];remaining=mins*60;
modal(`<h2>Class ${s.cls} Mathematics Examination</h2><p class="muted">${esc(s.name)} · ${qs.length} questions · ${mins} minutes</p><div class="timer" id="timer">Time remaining: ${fmt(remaining)}</div><form id="examForm">${qs.map((q,i)=>`<div class="question"><b>Q${i+1}. ${esc(q.q)}</b>${q.opts.map((o,j)=>`<label class="option"><input type="radio" name="q${i}" value="${j}"> ${esc(o)}</label>`).join('')}</div>`).join('')}<button class="primary wide">Submit examination</button></form>`);
examTimer=setInterval(()=>{remaining--;let t=document.getElementById('timer');if(t)t.textContent='Time remaining: '+fmt(remaining);if(remaining<=0){clearInterval(examTimer);examTimer=null;submitExam(s,qs,true)}},1000);
document.getElementById('examForm').onsubmit=e=>{e.preventDefault();if(confirm('Submit your examination now?'))submitExam(s,qs,false)}}
function submitExam(s,qs,auto){if(examTimer)clearInterval(examTimer);examTimer=null;let form=document.getElementById('examForm'),score=0,answers=[];qs.forEach((q,i)=>{let a=form?.querySelector(`input[name="q${i}"]:checked`);let val=a?Number(a.value):-1;answers.push(val);if(val===q.ans)score++});let r={id:s.id,score,total:qs.length,answers,submitted:new Date().toISOString()};db.results.push(r);save();modal(`<h2>Examination submitted</h2><div class="success-panel">Your answers have been recorded on this device.</div><p>${auto?'Your time ended and the test was automatically submitted.':'Thank you for completing the examination.'}</p><p class="muted">Your result will be shown after the organiser publishes results.</p><button class="primary wide" onclick="showStudent()">Back to student area</button>`)}
function fmt(n){return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0')}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
document.addEventListener('click',e=>{if(e.target.id==='adminLogin'){if(document.getElementById('adminPin').value!==ADMIN_PIN){toast('Incorrect admin PIN');return}adminDashboard('overview')}});
function adminDashboard(tab){let content='';if(tab==='overview'){content=`<div class="stats"><div><b>${db.students.length}</b><small>Registrations</small></div><div><b>${db.results.length}</b><small>Attempts</small></div><div><b>${db.examOpen?'OPEN':'CLOSED'}</b><small>Exam status</small></div><div><b>${db.published?'YES':'NO'}</b><small>Results published</small></div></div><div class="admin-note">Local demo data is stored only in this browser. It is not shared with other computers or students.</div>`}
if(tab==='students'){content=`<h3>Registered students (${db.students.length})</h3><div class="table-wrap"><table><thead><tr><th>Olympiad ID</th><th>Name</th><th>Class</th><th>School</th><th>City</th><th>Mobile</th></tr></thead><tbody>${db.students.map(s=>`<tr><td>${s.id}</td><td>${esc(s.name)}</td><td>${s.cls}</td><td>${esc(s.school)}</td><td>${esc(s.city)}</td><td>${s.phone}</td></tr>`).join('')}</tbody></table></div><button class="secondary" id="exportStudents">Export registrations CSV</button>`}
if(tab==='results'){let rows=db.results.map(r=>{let s=db.students.find(x=>x.id===r.id)||{};return {...r,name:s.name||'',cls:s.cls||'',school:s.school||''}}).sort((a,b)=>b.score/b.total-a.score/a.total);content=`<h3>Exam results (${rows.length})</h3><div class="table-wrap"><table><thead><tr><th>Student</th><th>Class</th><th>School</th><th>Score</th><th>Submitted</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.name)}</td><td>${r.cls}</td><td>${esc(r.school)}</td><td>${r.score}/${r.total}</td><td>${new Date(r.submitted).toLocaleString()}</td></tr>`).join('')}</tbody></table></div><button class="secondary" id="exportResults">Export results CSV</button>`}
if(tab==='settings'){content=`<h3>Competition controls</h3><p class="muted">These settings apply to this browser's local demo only.</p><p>Exam access: <b>${db.examOpen?'Open':'Closed'}</b></p><button class="${db.examOpen?'danger':'primary'}" id="toggleExam">${db.examOpen?'Close':'Open'} examination</button><p style="margin-top:18px">Results publication: <b>${db.published?'Published':'Not published'}</b></p><button class="secondary" id="togglePublish">${db.published?'Unpublish':'Publish'} results & certificates</button><hr><button class="danger" id="resetDemo">Reset all demo data</button>`}
modal(`<h2>Administrator dashboard</h2><p class="muted">S.B.S. Mathematics Olympiad · Local demonstration</p><div class="tabs">${[['overview','Overview'],['students','Registrations'],['results','Results'],['settings','Controls']].map(x=>`<button class="${x[0]===tab?'active':''}" data-tab="${x[0]}">${x[1]}</button>`).join('')}</div>${content}`);
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>adminDashboard(b.dataset.tab));
let es=document.getElementById('exportStudents');if(es)es.onclick=()=>csv('sbs_registrations.csv',['ID','Name','Class','School','City','Mobile','Guardian','Email'],db.students.map(s=>[s.id,s.name,s.cls,s.school,s.city,s.phone,s.guardian,s.email]));
let er=document.getElementById('exportResults');if(er)er.onclick=()=>csv('sbs_results.csv',['ID','Score','Total','Submitted'],db.results.map(r=>[r.id,r.score,r.total,r.submitted]));
let te=document.getElementById('toggleExam');if(te)te.onclick=()=>{db.examOpen=!db.examOpen;save();adminDashboard('settings')};
let tp=document.getElementById('togglePublish');if(tp)tp.onclick=()=>{db.published=!db.published;save();adminDashboard('settings')};
let reset=document.getElementById('resetDemo');if(reset)reset.onclick=()=>{if(confirm('Permanently clear all local demo registrations and results?')){db={students:[],results:[],examOpen:true,published:false};save();adminDashboard('overview')}};
}
function csv(name,heads,rows){let q=v=>'"'+String(v??'').replace(/"/g,'""')+'"';let data=[heads,...rows].map(r=>r.map(q).join(',')).join('\n');let a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+data],{type:'text/csv'}));a.download=name;a.click();URL.revokeObjectURL(a.href)}
function certificate(s,r){modal(`<div class="certificate" id="certificate"><div style="letter-spacing:3px;font-weight:bold">S.B.S. SCHOOL, TALEN</div><small>CBSE Affiliation No. 1031489</small><h1>Certificate of Participation</h1><p>This certificate is proudly presented to</p><div class="name">${esc(s.name)}</div><p>of <b>${esc(s.school)}</b>, Class <b>${s.cls}</b></p><p>for participating in the</p><h2>S.B.S. Mathematics Olympiad 2026–27</h2><p>Organised by S.B.S. School, Talen, Madhya Pradesh</p><p style="margin-top:35px">Olympiad ID: ${s.id}</p><div style="display:flex;justify-content:space-between;margin-top:40px"><span>_________________<br>Coordinator</span><span>_________________<br>Principal / Director</span></div></div><button class="primary wide" style="margin-top:15px" onclick="window.print()">Print / Save as PDF</button>`)}
window.showLogin=showLogin;window.showStudent=showStudent;
